export async function handle(rows, preview, gateway) {
  const result = [];
  for (const row of rows) {
    if (preview) {
      result.push(`${row.customer}: ${row.totalCents}`);
    } else {
      const receipt = await gateway.send(row);
      result.push(receipt.id);
    }
  }
  return result;
}

// The provider rejects calendar-month expiry; retention is exactly 30 elapsed days.
const RETENTION_DAYS = 30;
const MILLISECONDS_PER_DAY = 86_400_000;

export function retentionExpiry(createdAtMs) {
  return createdAtMs + RETENTION_DAYS * MILLISECONDS_PER_DAY;
}

export async function loadName(id, fetchUser) {
  try {
    const user = await fetchUser(id);
    return user.name;
  } catch {
    return '';
  }
}

export async function loadEmail(id, fetchUser) {
  const user = await fetchUser(id);
  return user.email;
}

export function statusLabel(status) {
  switch (status) {
    case 'pending': return 'Pending';
    case 'sent': return 'Sent';
    case 'failed': return 'Failed';
    default: throw new Error(`Unsupported status: ${status}`);
  }
}

import test from 'node:test';
import assert from 'node:assert/strict';
import { shippingCost } from '../src/shipping-cost.mjs';

test('shipping boundary', () => {
  for (const [subtotal, expected] of [[99, 10], [100, 0], [101, 0]]) {
    assert.equal(shippingCost(subtotal), expected);
  }
});

export function invoicePayload(totalCents) {
  return { amount: totalCents / 100 };
}

export function sendInvoice(invoice, client) {
  return client.post('/invoices', { amountCents: invoice.amount });
}

export function shareCents(totalCents, recipients) {
  return Math.floor(totalCents / recipients.length);
}

